cd "E:/project/AIc/ship-sentinel/samples" && cat > /tmp/dump2.py <<'PY'
import openpyxl, glob, io, json
out = []
for f in glob.glob("**/*.xlsx", recursive=True):
    entry = {"file": f.replace("\\","/"), "sheets": []}
    wb = openpyxl.load_workbook(f, data_only=True)
    for ws in wb.worksheets:
        s = {"sheet": ws.title, "dims": f"{ws.max_row}x{ws.max_column}", "rows": []}
        for i, row in enumerate(ws.iter_rows(values_only=True)):
            s["rows"].append([("" if c is None else str(c)) for c in row])
            if i >= 4:
                break
        entry["sheets"].append(s)
    wb.close()
    out.append(entry)
with io.open("/tmp/dump.json","w",encoding="utf-8") as fh:
    json.dump(out, fh, ensure_ascii=False, indent=2)
print("done")
PY
python /tmp/dump2.py 2>&1 | grep -v Warning | tail -3

